    "inlineSchema": "generator client {\n  provider     = \"prisma-client\"\n  output       = \"../generated/prisma\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ── Enums ─────────────────────────────────────────────\n\nenum ListingCategory {\n  Cameras\n  PowerTools\n  Bikes\n  CampingGear\n}\n\nenum ListingStatus {\n  active\n  paused\n  pending\n  rejected\n}\n\nenum BookingStatus {\n  pending\n  confirmed\n  completed\n  cancelled\n}\n\nenum PayoutStatus {\n  pending\n  paid\n  on_hold\n}\n\nenum PickupMethod {\n  pickup\n  delivery\n}\n\nenum DisputeStatus {\n  flagged\n  under_review\n  resolved\n}\n\nenum CardBrand {\n  Visa\n  Mastercard\n}\n\n// ── Core entities ─────────────────────────────────────\n\nmodel User {\n  id           String   @id @default(uuid())\n  name         String\n  email        String   @unique\n  passwordHash String\n  initials     String\n  // Every user can rent. isOwner flips on once they create their first\n  // listing — this replaces a renter/owner enum so one account can do both,\n  // matching the \"same account, role-based\" decision from the design phase.\n  isOwner      Boolean  @default(false)\n  isSuspended  Boolean  @default(false)\n  memberSince  DateTime @default(now())\n  responseTime String?\n\n  listings               Listing[]\n  bookings               Booking[]       @relation(\"RenterBookings\")\n  paymentMethods         PaymentMethod[]\n  messages               Message[]\n  messageThreadsAsRenter MessageThread[] @relation(\"RenterThreads\")\n\n  @@map(\"users\")\n}\n\nmodel Listing {\n  id          String          @id @default(uuid())\n  title       String\n  category    ListingCategory\n  location    String\n  pricePerDay Decimal         @db.Decimal(10, 2)\n  description String          @db.Text\n  status      ListingStatus   @default(pending)\n  createdAt   DateTime        @default(now())\n\n  ownerId String\n  owner   User   @relation(fields: [ownerId], references: [id])\n\n  bookings Booking[]\n  threads  MessageThread[]\n\n  // Note: mock data's unavailableDaysOfMonth is gone entirely. Availability\n  // is now derived by querying confirmed Bookings whose date range overlaps\n  // the requested dates — a stored list would drift out of sync with actual\n  // bookings the moment one is cancelled or added.\n\n  @@map(\"listings\")\n}\n\nmodel Booking {\n  id            String        @id @default(uuid())\n  requestNumber String        @unique @default(cuid())\n  status        BookingStatus @default(pending)\n  startDate     DateTime      @db.Date\n  endDate       DateTime      @db.Date\n  pickupMethod  PickupMethod\n  payoutStatus  PayoutStatus?\n  createdAt     DateTime      @default(now())\n\n  // Pricing snapshot at time of booking — stored, not recomputed, since\n  // Listing.pricePerDay can change later and a past booking's receipt\n  // shouldn't retroactively change with it.\n  pricePerDayAtBooking Decimal @db.Decimal(10, 2)\n  nights               Int\n  subtotal             Decimal @db.Decimal(10, 2)\n  serviceFee           Decimal @db.Decimal(10, 2)\n  tax                  Decimal @db.Decimal(10, 2)\n  total                Decimal @db.Decimal(10, 2)\n\n  listingId String\n  listing   Listing @relation(fields: [listingId], references: [id])\n\n  renterId String\n  renter   User   @relation(\"RenterBookings\", fields: [renterId], references: [id])\n\n  paymentMethodId String\n  paymentMethod   PaymentMethod @relation(fields: [paymentMethodId], references: [id])\n\n  dispute Dispute?\n\n  // TODO before going live: Postgres can't enforce \"no overlapping date\n  // ranges per listing\" through Prisma alone — that needs a raw SQL\n  // migration adding an EXCLUDE constraint (via the btree_gist extension)\n  // on (listingId, daterange(startDate, endDate)). Until that migration\n  // exists, this check has to happen in the booking service, not the DB.\n\n  @@map(\"bookings\")\n}\n\nmodel PaymentMethod {\n  id                       String    @id @default(uuid())\n  brand                    CardBrand\n  last4                    String\n  expires                  String\n  // Stripe (or whichever processor) token — the actual card number/CVV\n  // never touches this database. last4/expires are just what Stripe\n  // returns for display; this field is what actually charges the card.\n  processorPaymentMethodId String    @unique\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  bookings Booking[]\n\n  @@map(\"payment_methods\")\n}\n\nmodel MessageThread {\n  id              String   @id @default(uuid())\n  unreadForRenter Boolean  @default(false)\n  unreadForOwner  Boolean  @default(false)\n  createdAt       DateTime @default(now())\n\n  listingId String\n  listing   Listing @relation(fields: [listingId], references: [id])\n\n  renterId String\n  renter   User   @relation(\"RenterThreads\", fields: [renterId], references: [id])\n  // Owner is intentionally not a separate FK here — it's always\n  // listing.owner. Storing it again would let it silently drift if a\n  // listing ever changed hands.\n\n  messages Message[]\n\n  @@map(\"message_threads\")\n}\n\nmodel Message {\n  id     String   @id @default(uuid())\n  text   String   @db.Text\n  sentAt DateTime @default(now())\n\n  threadId String\n  thread   MessageThread @relation(fields: [threadId], references: [id])\n\n  senderId String\n  sender   User   @relation(fields: [senderId], references: [id])\n  // Whether the sender was acting as \"renter\" or \"owner\" for this message\n  // is derived by comparing senderId to thread.renterId vs listing.ownerId\n  // — not stored, since it's fully computable and storing it risks drift.\n\n  @@map(\"messages\")\n}\n\nmodel Dispute {\n  id     String        @id @default(uuid())\n  status DisputeStatus @default(flagged)\n  detail String        @db.Text\n\n  bookingId String  @unique\n  booking   Booking @relation(fields: [bookingId], references: [id])\n  // Replaces the old free-text \"parties\" field — renter, owner, and\n  // listing are all reachable through booking.renter and\n  // booking.listing.owner instead of being duplicated as text.\n\n  @@map(\"disputes\")\n}\n\n// ── Staff / admin (separate auth domain) ──────────────\n\nmodel AdminUser {\n  id           String   @id @default(uuid())\n  name         String\n  email        String   @unique\n  passwordHash String\n  initials     String\n  createdAt    DateTime @default(now())\n\n  @@map(\"admin_users\")\n}\n",
